static int n;static void Check(bool value,string name){n++;if(!value)throw new Exception(name);}static void Near(double a,double b,string name){Check(Math.Abs(a-b)<=1e-9*Math.Max(1,Math.Abs(b)),name);}static void Reject(Action action,string name){bool bad=false;try{action();}catch(InvalidDataException){bad=true;}Check(bad,name);}
