static ReturnConductorRating Conductor(ReturnRole role,double r,double x){return new ReturnConductorRating{Role=role,Material=ConductorMaterial.Copper,SectionMm2=35,CorrectedIzA=80,ResistanceOhmKm=r,ReactanceOhmKm=x,Reference="QA-"+role,Source="QA",DataVersion="2026",Conditions="60Hz"};}
static ContactTimeRule Rule(EarthingScheme scheme){return new ContactTimeRule{Mode=ContactRuleMode.TransientContactAndTime,Scheme=scheme,CircuitClass=RuleCircuitClass.Final,MinimumU0V=200,MaximumU0V=240,UsesRatedCurrentLimit=true,MaximumRatedA=63,TouchLimitV=50,MaximumDisconnectSeconds=.4,PotentialReference=scheme==EarthingScheme.TNS?FaultVoltageReference.SourceNeutral:FaultVoltageReference.RemoteEarth,Reference="Regra sintética QA",Edition="QA2026",Clause="Ensaio",Conditions="Somente o caso nominal/modelo declarado"};}
static ClearingTimeRecord Record(Project p,Circuit c,ClearingDevice device){var row=ContactTime.Template(p,c,device);row.MinimumCurrentA=device==ClearingDevice.SelectedResidual?.15:100;row.MaximumCurrentA=10000;row.UpperSeconds=.1;row.CoversTotalClearing=true;row.IncludesExternalActuator=true;row.Source="Tempo TOTAL sintético QA";row.DataVersion="2026.10";row.Conditions="Ensaio QA; tempo até interrupção, não ajuste";return row;}
static void Residual(Project p,Circuit c,PoleLayout poles=PoleLayout.FourPole){c.ResidualSelection=new ResidualBinding{Engine=ResidualSelection.EngineId,RequiredWaveform=ResidualWaveform.A,RequiredPoles=poles,MaximumDeltaMilliA=30,RequirementSource="QA",Rating=new ResidualRating{Kind=ResidualKind.RCCB,Manufacturer="QA",Reference="RCD63",Waveform=ResidualWaveform.A,VoltageV=400,FrequencyHz=60,Poles=poles,RatedA=63,DeltaMilliA=30,ConditionalKA=15,RequiredPrimaryConfiguration=ResidualSelection.PrimaryConfiguration(c),AssemblyDocument="Associação QA",Source="QA",DataVersion="2026.10",Standard="QA",Conditions="Ensaio nominal"}};}
